POST /api/v1/seasons/{season_id}/simulation-jobs
Authorization: Bearer <token>
Idempotency-Key: <unique-request-key>
Content-Type: application/json

{
  "run_kind": "calibration",
  "as_of_date": "2026-10-08",
  "profile_id": "<validated-profile-id>",
  "observation_policy": "accepted_only"
}

HTTP 202
{
  "job_id": "<uuid>",
  "status": "queued",
  "input_revision": 12,
  "status_url": "/api/v1/jobs/<uuid>"
}

HTTP 422
{
  "error": {
    "code": "WEATHER_GAP",
    "message": "运行期间存在未处理的天气缺测",
    "request_id": "<uuid>"
  }
}
